func TestVersionSyncJobRunsImmediatelyAndOnInterval(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	calls := make(chan struct{}, 3)
	done := StartVersionSyncJob(ctx, 10*time.Millisecond, func(context.Context) {
		calls <- struct{}{}
	})

	for range 2 {
		select {
		case <-calls:
		case <-time.After(time.Second):
			cancel()
			t.Fatal("scheduled version sync did not run")
		}
	}

	cancel()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("scheduled version sync did not stop after cancellation")
	}
}

func TestVersionSyncJobDoesNotStartWithInvalidInterval(t *testing.T) {
	called := false
	done := StartVersionSyncJob(context.Background(), 0, func(context.Context) {
		called = true
	})
	<-done
	if called {
		t.Fatal("sync ran with a non-positive interval")
	}
}
